### ✅ Merge Sort in C (No `malloc`, No dynamic allocation)

```c
#include <stdio.h>

#define MAX 100  // Maximum array size

// Function to merge two sorted parts
void merge(int arr[], int left, int mid, int right) {
    int i, j, k;

    int n1 = mid - left + 1;
    int n2 = right - mid;

    // Temporary arrays with max size
    int L[MAX], R[MAX];

    // Copy data into temp arrays L[] and R[]
    for (i = 0; i < n1; i++)
        L[i] = arr[left + i];
    for (j = 0; j < n2; j++)
        R[j] = arr[mid + 1 + j];

    i = 0;  // Initial index of L[]
    j = 0;  // Initial index of R[]
    k = left;  // Initial index of merged subarray

    // Merge L[] and R[] into arr[]
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k++] = L[i++];
        } else {
            arr[k++] = R[j++];
        }
    }

    // Copy remaining elements of L[]
    while (i < n1) {
        arr[k++] = L[i++];
    }

    // Copy remaining elements of R[]
    while (j < n2) {
        arr[k++] = R[j++];
    }
}

// Recursive merge sort function
void mergeSort(int arr[], int left, int right) {
    if (left < right) {
        int mid = (left + right) / 2;

        // Sort left and right halves
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);

        // Merge sorted halves
        merge(arr, left, mid, right);
    }
}

// Main function to test
int main() {
    int arr[] = {38, 27, 43, 3, 9, 82, 10};
    int size = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }

    mergeSort(arr, 0, size - 1);

    printf("\nSorted array: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }

    return 0;
}
```

---

### ⚠️ Notes:

- `#define MAX 100`: Sets max size for temporary arrays `L[]` and `R[]`. Make sure it’s **greater than or equal to half the array size**, or you risk overflow.
- This version is **safe, clean, and simple** for small arrays. For large-scale production code, dynamic allocation is preferred.

